import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.ext.ExceptionMapper;
import jakarta.ws.rs.ext.Provider;
import jakarta.ws.rs.Consumes;
import jakarta.ws.rs.Produces;
import java.util.Map;

@Path("/parcels")
@Consumes(MediaType.APPLICATION_JSON)
@Produces(MediaType.APPLICATION_JSON)
public class ParcelResource {

    public record RegisterParcelRequest(@NotBlank String parcelId, @NotNull @Positive Double weightKg) {
    }

    @Inject
    ParcelService service;

    @POST
    public Response register(@Valid @NotNull RegisterParcelRequest request) {
        Parcel parcel = service.register(new Parcel(request.parcelId(), request.weightKg()));
        return Response.status(Response.Status.CREATED).entity(parcel).build();
    }

    @Provider
    public static class TooHeavyMapper implements ExceptionMapper<ParcelTooHeavyException> {
        @Override
        public Response toResponse(ParcelTooHeavyException e) {
            return Response.status(422).entity(Map.of("error", e.getMessage())).build();
        }
    }
}
