import jakarta.enterprise.context.ApplicationScoped;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@ApplicationScoped
public class ParcelService {
    public static final double MAX_WEIGHT_KG = 30;

    private final Map<String, Parcel> parcels = new ConcurrentHashMap<>();

    public Parcel register(Parcel parcel) {
        if (parcel.weightKg() > MAX_WEIGHT_KG) {
            throw new ParcelTooHeavyException(parcel.parcelId(), parcel.weightKg());
        }
        parcels.put(parcel.parcelId(), parcel);
        return parcel;
    }

    public boolean contains(String parcelId) {
        return parcels.containsKey(parcelId);
    }
}
